// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX3 c;

    // The test contract becomes Owner at setUp (msg.sender == this), so it must
    // be able to receive the ETH that withdraw() transfers out.
    receive() external payable {}

    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: fund the contract with more than 1 wei.
        vm.assume(amount > 1);
        vm.assume(amount < type(uint128).max);

        // Fund c directly through its receive().
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);

        // Owner (this contract) withdraws the whole balance.
        vm.prank(address(this));
        bool ok; try c.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok);

        // General rule: after an owner withdraw() succeeds, c's balance is fully drained.
        assertTrue(address(c).balance == 0);
    }
}
